class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        if n == 0:
            return 0

        operations = 0
        i = 0
        while i < n - 1:
            current_char = word[i]
            next_char = word[i+1]
            if current_char == next_char or abs(ord(current_char) - ord(next_char)) == 1:
                operations += 1
                i += 2  # skip the next character as it's handled
            else:
                i += 1
        return operations
```

